108	/**
109	 * Encode a Python `str` as UTF-8 with `errors='strict'`, raising
110	 * `UnicodeEncodeError` for lone surrogates — including the surrogate-escaped
111	 * bytes produced by {@link decodeSurrogateEscape}.
112	 *
113	 * @param {string} text
114	 * @returns {Uint8Array}
115	 */
116	export function encodeUtf8Strict(text) {
117	  const codePoints = Array.from(text);
118	  for (let i = 0; i < codePoints.length; i += 1) {
119	    const point = codePoints[i].codePointAt(0);
120	    if (point >= SURROGATE_LOW && point <= SURROGATE_HIGH) {
121	      // CPython reports the whole run of consecutive offenders as one range.
122	      let end = i + 1;
123	      while (end < codePoints.length) {
124	        const next = codePoints[end].codePointAt(0);
125	        if (next < SURROGATE_LOW || next > SURROGATE_HIGH) break;
126	        end += 1;
127	      }
128	      throw new UnicodeEncodeError('utf-8', text, i, end, 'surrogates not allowed');
129	    }
130	  }
131	  return new Uint8Array(Buffer.from(text, 'utf8'));
