13	  /**
14	   * @param {string} pythonType name as it appears in a traceback
15	   * @param {string} message the exception's `str()`
16	   */
17	  constructor(pythonType, message) {
18	    super(message);
19	    this.pythonType = pythonType;
20	    /** Frames appended below the caller's frames, innermost last. */
21	    this.pythonFrames = [];
22	  }
23	}
