35	 *
36	 * CPython renders it as
37	 *   'utf-8' codec can't encode character '\udcff' in position 13: <reason>
38	 * for a single offending code point and
39	 *   'utf-8' codec can't encode characters in position 0-1: <reason>
40	 * for a run of two or more.
41	 */
42	export class UnicodeEncodeError extends PythonError {
43	  /**
44	   * @param {string} encoding e.g. 'utf-8'
45	   * @param {string} object the string being encoded
46	   * @param {number} start first offending code-point index
47	   * @param {number} end one past the last offending code-point index
48	   * @param {string} reason human-readable cause
49	   */
50	  constructor(encoding, object, start, end, reason) {
51	    super('UnicodeEncodeError', '');
52	    this.encoding = encoding;
53	    this.object = object;
54	    this.start = start;
55	    this.end = end;
56	    this.reason = reason;
57	    this.message = formatUnicodeEncodeError(this);
58	  }
59	}
