69	  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
70	  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
71	  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
72	}
