#!/usr/bin/env node
/** Standalone differential harness (independent of /workspace/verify/diff.mjs). */
import { spawn } from 'node:child_process';
import { chmodSync, copyFileSync, mkdirSync, readFileSync, existsSync } from 'node:fs';

const REF_ORIG = '/workspace/dataset/test13_executable';
const REF_COPY = '/tmp/myref/test13.mjs';
mkdirSync('/tmp/myref', { recursive: true });
if (!existsSync(REF_COPY)) {
  copyFileSync(REF_ORIG, REF_COPY);
  chmodSync(REF_COPY, 0o755);
}

const argv = process.argv.slice(2);
const casesPath = argv[0];
const opt = (n, d) => {
  const i = argv.indexOf(n);
  return i === -1 ? d : argv[i + 1];
};
const cwd = opt('--cwd', '/tmp');
const jobs = Number(opt('--jobs', '8'));
const verbose = argv.includes('--verbose');

const norm = (t) => t.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]');
const q = (t) => `'${String(t).replace(/'/g, `'\\''`)}'`;
function inv(cmd, args) {
  const parts = args.map((a) =>
    a && typeof a === 'object' && 'raw' in a ? `$'${a.raw}'` : q(a),
  );
  return `exec ${cmd.map(q).join(' ')} ${parts.join(' ')}`;
}
function run(cmd, args, env) {
  return new Promise((res) => {
    const child = spawn('bash', ['-c', inv(cmd, args)], {
      cwd,
      env: { ...process.env, ...(env || {}) },
    });
    const out = [];
