#!/usr/bin/env node
/** Generate random raw-byte argv cases biased toward UTF-8 edge bytes. */
const count = Number(process.argv[2] || 400);
let seed = Number(process.argv[3] || 1);
const rnd = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
const pick = (a) => a[Math.floor(rnd() * a.length)];

const ALPHABET = [
  // ascii
  0x41, 0x42, 0x7a, 0x30, 0x21, 0x0a, 0x20, 0x7f,
  // continuation bytes
  0x80, 0x8f, 0x9f, 0xa0, 0xbf, 0xb2,
  // bad leads
  0xc0, 0xc1, 0xf5, 0xf8, 0xfc, 0xfe, 0xff,
  // 2-byte leads
  0xc2, 0xc3, 0xdf,
  // 3-byte leads
  0xe0, 0xe1, 0xec, 0xed, 0xee, 0xef,
  // 4-byte leads
  0xf0, 0xf1, 0xf3, 0xf4,
];
const SEQS = [
  [0xc3, 0xa9],
  [0xe4, 0xb8, 0x96],
  [0xf0, 0x9f, 0x98, 0x80],
  [0xef, 0xbf, 0xbd],
  [0xed, 0xa0, 0x80],
  [0xed, 0xb2, 0x80],
  [0xf4, 0x8f, 0xbf, 0xbf],
  [0xf4, 0x90, 0x80, 0x80],
  [0xf8, 0x88, 0x80, 0x80, 0x80],
  [0xfc, 0x84, 0x80, 0x80, 0x80, 0x80],
  [0xc0, 0x80],
  [0xe0, 0x80, 0x80],
  [0xf0, 0x80, 0x80, 0x80],
];

function makeBytes(maxLen) {
  const out = [];
  const target = 1 + Math.floor(rnd() * maxLen);
  while (out.length < target) {
    if (rnd() < 0.35) {
      out.push(...pick(SEQS));
    } else {
      out.push(pick(ALPHABET));
    }
  }
  return out.slice(0, Math.max(1, out.length));
}

const esc = (bytes) =>
  bytes.map((b) => `\\x${b.toString(16).padStart(2, '0')}`).join('');

const lines = [];
for (let i = 0; i < count; i += 1) {
  const keyBytes = makeBytes(20);
  const dataBytes = makeBytes(20);
  const mode = i % 3;
  if (mode === 0) {
    lines.push(
      JSON.stringify({
        name: `fz-key#${i}`,
        args: ['--key', { raw: esc(keyBytes) }, '--data', 'BBBBBBBBBBBBBBBB'],
      }),
    );
  } else if (mode === 1) {
    lines.push(
      JSON.stringify({
        name: `fz-data#${i}`,
        args: ['--key', '0123456789abcdef', '--data', { raw: esc(dataBytes) }],
      }),
    );
  } else {
    lines.push(
      JSON.stringify({
        name: `fz-both#${i}`,
        args: ['--key', { raw: esc(keyBytes) }, '--data', { raw: esc(dataBytes) }],
      }),
    );
  }
}
process.stdout.write(lines.join('\n') + '\n');

